var datum, txt, SmartPlugSara, SmartPlugBen, HzgSaraButtonAktiviert, HzgBenButtonAktiviert, HzgSaraPVAktiviert, HzgBenPVAktiviert;

// Beschreibe diese Funktion …
async function Logfile(datum, txt) {
    require('fs').appendFileSync('/opt/iobroker/log/' + datum + ' - smartplug.log', formatDate(new Date(), "hh:mm:ss") + " \t" + txt + "\n");
}


// INIT--------------
createState('0_userdata.0.SmartPlugs.SmarPlug_HzgBen', false, ((common) => typeof common !== 'object' ? JSON.parse(common) : common)('{"name": "SmartPlug_HzgBen","role": "","type": "boolean","desc": "Blockly erzeugt","read": true,"write": true,"def": false}'), async () => {
});
createState('0_userdata.0.SmartPlugs.SmarPlug_HzgSara', false, ((common) => typeof common !== 'object' ? JSON.parse(common) : common)('{"name": "SmartPlug_HzgSara","role": "","type": "boolean","desc": "Blockly erzeugt","read": true,"write": true,"def": false}'), async () => {
});
createState('0_userdata.0.SmartPlugs.SmartPlugSara_Timeout', 0, ((common) => typeof common !== 'object' ? JSON.parse(common) : common)('{"name": "SmartPlugSara_Timeout","role": "","type": "number","desc": "Blockly erzeugt","unit": "","min": 0,"max": 10000,"def": 0,"read": true,"write": true}'), async () => {
});
createState('0_userdata.0.SmartPlugs.SmartPlugBen_Timeout', 0, ((common) => typeof common !== 'object' ? JSON.parse(common) : common)('{"name": "SmartPlugBen_Timeout","role": "","type": "number","desc": "Blockly erzeugt","unit": "","min": 0,"max": 10000,"def": 0,"read": true,"write": true}'), async () => {
});
createState('0_userdata.0.SmartPlugs.SmarPlug_Debug', false, ((common) => typeof common !== 'object' ? JSON.parse(common) : common)('{"name": "SmartPlug_Debug","role": "","type": "boolean","desc": "Blockly erzeugt","read": true,"write": true,"def": false}'), async () => {
});
// Überwachung ---------------------
schedule("*/5 * * * * *", async () => {
  if (getState('0_userdata.0.AMIS.Grid_Überwachung').val) {
    setState('shelly.0.SHPLG-S#8044C6#1.Relay0.Switch' /* Switch */, false, true);
    setState('shelly.0.SHPLG-S#EED8F9#1.Relay0.Switch' /* Switch */, false, true);
  }
  if (getState('0_userdata.0.AMIS.PVÜberschuss').val == 0) {
    if (getState('shelly.0.SHPLG-S#8044C6#1.Relay0.Switch').val && !HzgBenButtonAktiviert) {
      setState('shelly.0.SHPLG-S#8044C6#1.Relay0.Switch' /* Switch */, false, true);
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Hzg Ben musste abgedreht werden. PV-Überschuss (W): ' + String(('' + getState('0_userdata.0.AMIS.PVÜberschuss').val)));
    }
    if (getState('shelly.0.SHPLG-S#EED8F9#1.Relay0.Switch').val && !HzgSaraButtonAktiviert) {
      setState('shelly.0.SHPLG-S#EED8F9#1.Relay0.Switch' /* Switch */, false, true);
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Hzg Sara musste abgedreht werden. PV-Überschuss (W): ' + String(('' + getState('0_userdata.0.AMIS.PVÜberschuss').val)));
    }
  }
});
// Timeouts
schedule("* * * * * *", async () => {
  setState('0_userdata.0.SmartPlugs.SmartPlugSara_Timeout' /* SmartPlugSara_Timeout */, (Math.min(Math.max(getState('0_userdata.0.SmartPlugs.SmartPlugSara_Timeout').val - 1, 0), 1000)));
  setState('0_userdata.0.SmartPlugs.SmartPlugBen_Timeout' /* SmartPlugBen_Timeout */, (Math.min(Math.max(getState('0_userdata.0.SmartPlugs.SmartPlugBen_Timeout').val - 1, 0), 1000)));
});

// Weihnachtsbeleuchtung

// Hzg Sara
SmartPlugSara = false;
HzgSaraButtonAktiviert = false;
HzgSaraPVAktiviert = false;
schedule("* * * * * *", async () => {
  if (getState('0_userdata.0.SmartPlugs.SmarPlug_Debug').val) {
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '- PV-Überschuss (W) : ' + String(('' + getState('0_userdata.0.AMIS.PVÜberschuss').val)));
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '- Status SmartPlugSara: ' + String(('' + SmartPlugSara)));
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '- Status HzgSaraPV: ' + String(('' + HzgSaraPVAktiviert)));
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), '- Status HzgSaraHand: ' + String(('' + HzgSaraButtonAktiviert)));
  }
  // Aktiv ?
  if (getState('0_userdata.0.SmartPlugs.SmarPlug_HzgSara').val && !getState('0_userdata.0.AMIS.Grid_Überwachung').val) {
    // De-/Aktivieren
    if (!HzgSaraButtonAktiviert && getState('0_userdata.0.SmartPlugs.SmartPlugSara_Timeout').val <= 0) {
      if (getState('0_userdata.0.AMIS.PVÜberschuss').val <= 250 && SmartPlugSara) {
        SmartPlugSara = false;
        HzgSaraPVAktiviert = false;
        if (getState('0_userdata.0.SmartPlugs.SmarPlug_Debug').val) {
          await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'SmartPlug Sara deaktiviert: ' + String(('' + SmartPlugSara)));
        }
      } else if (getState('0_userdata.0.AMIS.PVÜberschuss').val > 1500 && getState('alias.0.Gobel.SOC').val > 50 && !SmartPlugSara) {
        SmartPlugSara = true;
        HzgSaraPVAktiviert = true;
        if (getState('0_userdata.0.SmartPlugs.SmarPlug_Debug').val) {
          await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'SmartPlug Sara aktiviert: ' + String(('' + SmartPlugSara)));
        }
      } else if (!HzgSaraPVAktiviert && !SmartPlugSara && getState('shelly.0.SHPLG-S#EED8F9#1.Relay0.Switch').val) {
        SmartPlugSara = true;
        HzgSaraButtonAktiviert = true;
        if (getState('0_userdata.0.SmartPlugs.SmarPlug_Debug').val) {
          await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'SmartPlug Sara Button aktiviert: ' + String(('' + HzgSaraButtonAktiviert)));
        }
      }
      // ansteuern
      if (getState('shelly.0.SHPLG-S#EED8F9#1.Relay0.Switch').val != SmartPlugSara) {
        setState('shelly.0.SHPLG-S#EED8F9#1.Relay0.Switch' /* Switch */, SmartPlugSara);
        if (getState('0_userdata.0.SmartPlugs.SmarPlug_Debug').val) {
          await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Smart Plug Sara geändert: ' + String(('' + SmartPlugSara)));
        }
        if (!SmartPlugSara) {
          setState('0_userdata.0.SmartPlugs.SmartPlugSara_Timeout' /* SmartPlugSara_Timeout */, 310);
          if (getState('0_userdata.0.SmartPlugs.SmarPlug_Debug').val) {
            await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Smart Plug Sara Timeout: ' + String(('' + getState('0_userdata.0.SmartPlugs.SmartPlugSara_Timeout').val)));
          }
        }
      }
    }
  }
});
// HAND
on({ id: 'shelly.0.SHPLG-S#EED8F9#1.Relay0.Switch' /* Switch */, val: true, ack: true }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if (!HzgSaraPVAktiviert) {
    HzgSaraButtonAktiviert = true;
    if (getState('0_userdata.0.SmartPlugs.SmarPlug_Debug').val) {
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'SmartPlug Sara per Hand eingeschaltet');
    }
  }
});
on({ id: 'shelly.0.SHPLG-S#EED8F9#1.Relay0.Switch' /* Switch */, val: false, ack: true }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if (HzgSaraButtonAktiviert && HzgSaraButtonAktiviert) {
    HzgSaraButtonAktiviert = false;
    if (getState('0_userdata.0.SmartPlugs.SmarPlug_Debug').val) {
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'SmartPlug Sara per Hand ausgeschaltet');
    }
  }
});

